  --accent-primary: #2563eb;
  --accent-primary-hover: #1d4ed8;
  --accent-primary-light: #dbeafe;
  --text-on-accent: #ffffff;
  --accent-success: #059669;
  --accent-warning: #b45309;
  --accent-error: #b91c1c;
  --accent-teal: #0d9488;
  --accent-info: #2563eb;
  --accent-fuchsia: #c026d3;
  --accent-sky: #0284c7;
  --accent-violet: #7c3aed;

  --surface-card: #ffffff;
  --surface-hover: #f1f5f9;
  --surface-active: #e2e8f0;
  --surface-selected: #eff6ff;
  --bg-overlay: rgba(0, 0, 0, 0.4);
  --surface-input: #ffffff;

  --grid-line: rgba(37, 99, 235, 0.1);
  --shadow-sm: 0 1px 3px 0 #0000001a, 0 1px 2px -1px #0000001a;
  --shadow-md: 0 4px 6px -1px #0000001a, 0 2px 4px -1px #0000000f;
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05); /* legacy globals.css (controller desk D2) */

  --sky-bg: rgba(14, 165, 233, 0.2); --sky-bd: rgba(2, 132, 199, 0.4); --sky-tx: #075985;
  --emer-bg: rgba(16, 185, 129, 0.18); --emer-bd: rgba(5, 150, 105, 0.4); --emer-tx: #065f46;
  --red-bg: rgba(239, 68, 68, 0.16); --red-bd: rgba(220, 38, 38, 0.45); --red-tx: #991b1b;
  --tag-early-bg: rgba(16, 185, 129, 0.16); --tag-early-tx: #047857; --tag-early-bd: rgba(16, 185, 129, 0.3);
